import Foundation

/// Protocol for types that provide metadata for schema generation.
/// Both StateNodes (via @StateNodeBuilder) and Actions/Events (via @Payload) conform to this.
public protocol SchemaMetadataProvider {
    /// Get metadata for all fields in this type.
    static func getFieldMetadata() -> [FieldMetadata]
}

/// The stored properties of a `@SnapshotConvertible` type that has no `init(fromSnapshotValue:)`
/// (a `let` property), generated by the macro (#566). The schema reads them when the type
/// declares no `SchemaMetadataProvider` itself: it has no sample instance to read them from, and
/// without them the schema lists no paths below the value while the diff produces them.
public protocol SnapshotFieldListProvider {
    static var snapshotFieldMetadata: [FieldMetadata] { get }
}
